<script setup lang="ts">
import{computed}from'vue';
import type{Participant}from'../../bindings/leaguepingo/internal/core/models';
import{rankPresentation}from'../rankPresentation';
import{percent,tierName}from'../presentation';
import RankEmblem from'./RankEmblem.vue';
const props=withDefaults(defineProps<{player:Participant;queue?:string}>(),{queue:'RANKED_SOLO_5x5'});
const data=computed(()=>rankPresentation(props.player,props.queue));
const title=(tier:string,division?:string)=>['NONE','UNRANKED'].includes(tier)?'未定级':`${tierName(tier)} ${['MASTER','GRANDMASTER','CHALLENGER'].includes(tier)?'':division??''}`.trim();
const label=computed(()=>props.queue==='RANKED_FLEX_SR'?'灵活组排':'单双排');
const history=computed(()=>[{label:'赛季最高',tier:data.value.rank?.highestTier,division:data.value.rank?.highestDivision},{label:'上赛季结算',tier:data.value.rank?.previousTier,division:data.value.rank?.previousDivision}].filter(r=>r.tier && !['NONE','UNRANKED'].includes(r.tier)));
</script>
<template><section class="rank-panel" :title="data.title"><header><h2>{{label}}</h2><span v-if="data.retained">旧资料</span></header><div class="rank-current"><RankEmblem :tier="data.rank?.tier"/><div><strong>{{data.rank?title(data.rank.tier,data.rank.division):data.label}}</strong><span>{{data.rank?.lp!=null?`${data.rank.lp.toLocaleString()} LP`:'—'}}</span></div><div class="rank-record" :title="data.record?.title"><b>{{percent(data.record?.rate)}}</b><small>{{data.record?`${data.record.wins.toLocaleString()} 胜 / ${data.record.losses.toLocaleString()} 负`:'胜负待确认'}}</small></div></div><details v-if="history.length" class="rank-history"><summary>最高与上季段位 <span>{{history[0]?.tier?title(history[0].tier,history[0].division):''}}</span></summary><div v-for="row in history" :key="row.label"><span>{{row.label}}</span><RankEmblem :tier="row.tier"/><b>{{title(row.tier!,row.division)}}</b></div></details></section></template>
<style scoped>.rank-panel{min-width:0;background:var(--panel);border:1px solid var(--border);border-radius:8px;overflow:hidden;}.rank-panel>header{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border-bottom:1px solid var(--border);height:36px;}.rank-panel h2{font-size:13px;font-weight:600;margin:0;}.rank-panel header>span{font-size:11px;color:var(--warning);}.rank-current{display:flex;gap:9px;align-items:center;padding:12px 10px;}.rank-current>.rank-emblem{width:48px;height:48px;flex:none;}.rank-current>div:not(.rank-record){min-width:0;flex:1;}.rank-current strong{font-size:14px;line-height:1.4;display:block;white-space:normal;overflow-wrap:anywhere;}.rank-current>div>span{font-size:12px;color:var(--muted);display:block;margin-top:4px;}.rank-record{text-align:right;flex:none;}.rank-record b{font-size:13px;font-weight:500;}.rank-record small{font-size:11px;color:var(--muted);display:block;margin-top:5px;white-space:nowrap;}.rank-history{border-top:1px solid var(--border);font-size:11px;color:var(--muted);}.rank-history summary{padding:8px 12px;cursor:pointer;}.rank-history summary>span{float:right;color:var(--text);}.rank-history>div{display:flex;align-items:center;gap:6px;padding:6px 12px;}.rank-history>div>span{flex:1;}.rank-history .rank-emblem{width:28px;height:28px;}.rank-history b{font-size:12px;font-weight:500;color:var(--text);}</style>
